def sha256_file(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def verify_contract(path: Path) -> None:
    if not path.is_file():
        raise FileNotFoundError(f"Actual OII-013 module missing: {path}")
    source = path.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "OII-013"',
        "class ScientificReasoningSessionActivationPackage",
        "class DisciplineActivationRecord",
        "def verify_scientific_reasoning_session_activation_package",
        "authorization_consumed",
        "activation_materialized",
        "invocation_manifest_allowed",
        "activation_token",
        "activation_status",
        "discipline_activations",
        "frozen_evidence_set_hash",
        "reasoning_execution_allowed",
        "probability_estimation_allowed",
        "final_intelligence_conclusion_allowed",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(
            "Actual OII-013 contract mismatch; missing: "
            + ", ".join(missing)
        )
    print("[OK] Actual OII-013 activation contract verified")


def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def append_export(path: Path, line: str) -> None:
    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    if line in existing.splitlines():
        print(f"[OK] PACKAGE EXPORT PRESENT: {path.resolve()}")
        return
    if existing and not existing.endswith("\n"):
        existing += "\n"
    path.write_text(existing + line + "\n", encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] PACKAGE UPDATED: {path.resolve()}")


def main() -> int:
    print("========================================")
    print(" OII-014 INSTALLER")
    print(" CONTROLLED REASONING INVOCATION MANIFEST")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit(
            "[ERROR] Run this installer from the kalshi-qss-bot repository root."
        )

    verify_contract(SOURCE_OII013)
    protected_hash = sha256_file(SOURCE_OII013)

    write_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_replacement(TEST, TEST_SOURCE)
    append_export(
        PACKAGE_INIT,
        "from .oracle_controlled_scientific_reasoning_invocation_manifest import *",
    )

    if sha256_file(SOURCE_OII013) != protected_hash:
        raise RuntimeError("Protected OII-013 module changed during installation")
    print("[PASS] Protected OII-013 module unchanged")

    completed = subprocess.run(
        [sys.executable, str(TEST)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode:
        raise SystemExit(completed.returncode)

    if sha256_file(SOURCE_OII013) != protected_hash:
        raise RuntimeError("Protected OII-013 module changed during testing")

    print("[PASS] Protected OII-013 module unchanged after test")
    print("[PASS] No acquisition, analytics, Operator, or Q Series module modified")
    print("[OK] OII-014 test executed automatically")
    print("[DONE] OII-014 CONTROLLED REASONING INVOCATION MANIFEST INSTALLED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
